# PowerShell completion for delva — generated by `delva completion powershell`
Register-ArgumentCompleter -Native -CommandName delva -ScriptBlock {
  param($wordToComplete, $commandAst, $cursorPosition)
  $valued = @('--store', '-s', '--width', '--key', '-k', '--path', '-p', '--line-width', '--max-levels', '--mode', '--nested', '--type', '-t', '--limit', '-n', '--order', '--after', '--max-bytes', '--where', '--normalization', '--fragment-size', '--index-key', '--exclude-key', '--min-indexed-string', '--max-indexed-string', '--document-key', '--replace', '--ignore-key', '--ignore-path', '--max-differences')
  $before = @($commandAst.CommandElements | Select-Object -Skip 1 |
    Where-Object { $_.Extent.EndOffset -lt $cursorPosition } | ForEach-Object { $_.ToString() })
  $words = @()
  $skip = $false
  foreach ($word in $before) {
    if ($skip) { $skip = $false; continue }
    if ($valued -ccontains $word) { $skip = $true } elseif ($word -notlike '-*') { $words += $word }
  }
  $previous = if ($before.Count -gt 0) { $before[-1] } else { '' }
  if (($valued -ccontains $previous) -and -not (@('--mode', '--nested', '--order', '--normalization') -ccontains $previous)) { return }
  $candidates = switch -CaseSensitive -Exact ($previous) {
    '--mode' { @('document', 'element') }
    '--nested' { @('all', 'outermost') }
    '--order' { @('asc', 'desc') }
    '--normalization' { @('none', 'nfc') }
    default {
      switch -CaseSensitive -Exact ($words -join ' ') {
        '' { @('info', 'get', 'search', 'explain', 'path', 'types', 'init', 'insert', 'delete', 'reset', 'verify', 'compare', 'completion', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'info' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'get' { @('--key', '-k', '--path', '-p', '--exit-status', '-e', '--pretty', '--compact', '--line-width', '--max-levels', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'search' { @('kv', 'path', 'key', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'search kv' { @('--string', '-S', '--mode', '--nested', '--type', '-t', '--limit', '-n', '--order', '--after', '--max-bytes', '--count', '-c', '--exit-status', '-e', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'search path' { @('--scan', '--where', '--mode', '--nested', '--type', '-t', '--limit', '-n', '--order', '--after', '--max-bytes', '--count', '-c', '--exit-status', '-e', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'search key' { @('--limit', '-n', '--order', '--after', '--max-bytes', '--count', '-c', '--exit-status', '-e', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'explain' { @('--where', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'path' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'types' { @('list', 'count', 'objects', 'assign', 'clear', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'types list' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'types count' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'types objects' { @('--after', '--limit', '-n', '--exit-status', '-e', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'types assign' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'types clear' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'init' { @('--normalization', '--fragment-size', '--no-hash-terms', '--index-key', '--exclude-key', '--min-indexed-string', '--max-indexed-string', '--document-key', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'insert' { @('--type', '-t', '--replace', '--upsert', '-u', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'delete' { @('--dry-run', '--force', '-f', '--no-input', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'reset' { @('--force', '-f', '--no-input', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'verify' { @('--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'compare' { @('--diff', '-d', '--ignore-key', '--ignore-path', '--types', '--max-differences', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        'completion' { @('bash', 'zsh', 'fish', 'powershell', '--store', '-s', '--json', '--verbose', '-v', '--quiet', '-q', '--no-color', '--width', '--help') }
        default { @('--help') }
      }
    }
  }
  $candidates | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
    [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
  }
}
